CREATE OR ALTER PROCEDURE dbo.sp_cerrar_caja_core @IdUsuario INT,@IdSucursal INT,@MontoCierre DECIMAL(12,2),@Observaciones VARCHAR(500)=NULL AS BEGIN SET NOCOUNT ON;DECLARE @Id INT,@Esperado DECIMAL(12,2);SELECT TOP(1) @Id=id_sesion,@Esperado=monto_apertura FROM dbo.sesion_caja WHERE id_sucursal=@IdSucursal AND fecha_cierre IS NULL ORDER BY fecha_apertura DESC;IF @Id IS NULL THROW 50203,'No existe una caja abierta.',1;SELECT @Esperado=@Esperado+ISNULL(SUM(CASE WHEN v.tipo_pago='efectivo' AND ISNULL(r.estado,'')<>'Anulado' THEN r.monto ELSE 0 END),0) FROM dbo.venta v LEFT JOIN dbo.factura f ON f.id_venta=v.id_venta LEFT JOIN dbo.recibo r ON r.id_factura=f.id_factura WHERE v.id_sesion=@Id;SELECT @Esperado=@Esperado+ISNULL(SUM(monto),0) FROM dbo.abono WHERE id_sesion=@Id AND metodo_pago='efectivo';SELECT @Esperado=@Esperado-ISNULL(SUM(total),0) FROM dbo.compra WHERE id_sesion=@Id AND metodo_pago='efectivo';SELECT @Esperado=@Esperado-ISNULL(SUM(monto),0) FROM dbo.movimiento_caja_manual WHERE id_sesion=@Id AND tipo='salida';UPDATE dbo.sesion_caja SET fecha_cierre=GETDATE(),monto_cierre=@MontoCierre,monto_esperado=@Esperado,diferencia=@MontoCierre-@Esperado,observaciones=NULLIF(LTRIM(RTRIM(@Observaciones)),'') WHERE id_sesion=@Id;SELECT @Id IdSesion,CONCAT('CIE-',RIGHT('00000000'+CAST(@Id AS VARCHAR),8)) NumeroCierre,GETDATE() FechaCierre,@MontoCierre MontoCierre,@Esperado MontoEsperado,@MontoCierre-@Esperado Diferencia;END
GO
IF OBJECT_ID('dbo.sp_cerrar_caja','SN') IS NOT NULL DROP SYNONYM dbo.sp_cerrar_caja;
GO
CREATE SYNONYM dbo.sp_cerrar_caja FOR dbo.sp_cerrar_caja_core;
GO
